template<class T1, class D1, class T2, class D2>
bool operator!=(const std::unique_ptr<T1, D1>& x, const std::unique_ptr<T2, D2>& y);
// Implementation note: This function returns (x.get() != y.get()), comparing the raw pointers. The compiler may inline this, turning it into a direct pointer comparison without function call overhead, especially if unique_ptr is used in performance-critical code.
